"""Notes MCP server."""

from mcp.server import MCPServer
from mcp.server.mcpserver.exceptions import ToolError

NOTES: dict[str, str] = {}


def build_server() -> MCPServer:
    server = MCPServer("notes")

    @server.tool()
    def add_note(title: str, body: str) -> str:
        """Store a note under the given title."""
        NOTES[title] = body
        return f"saved {title}"

    @server.tool()
    def word_count(title: str) -> int:
        """Return the number of whitespace-separated words in the stored note."""
        if title not in NOTES:
            # ToolError reaches the model as an is_error result with this message;
            # any other exception would be reported only as a generic crash.
            raise ToolError(f"no such note: {title!r}")
        return len(NOTES[title].split())

    return server


if __name__ == "__main__":
    build_server().run()

